<?php
require __DIR__.'/../bootstrap.php'; require_admin(); ensure_cms_schema();
$type=(($_GET['type']??'post')==='page')?'page':'post'; $label=$type==='post'?'Posts':'Pages';
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();
 cms_publish_scheduled(); $action=(string)post('action',''); $ids=array_values(array_filter(array_map('intval',(array)post('ids',[]))));
 if($action==='bulk_edit'&&$ids){
   $set=[];$vals=[];
   $bs=(string)post('bulk_status','');$ba=(int)post('bulk_author',0);$bc=post('bulk_comments','');$bp=post('bulk_pings','');$bcat=trim((string)post('bulk_categories',''));$btag=trim((string)post('bulk_tags',''));
   if(in_array($bs,['draft','pending','published','private'],true)){$set[]='status=?';$vals[]=$bs;if($bs==='published'){$set[]='published_at=COALESCE(published_at,NOW())';}}
   if($ba>0){$set[]='author_id=?';$vals[]=$ba;}
   if($bc!==''&&in_array((string)$bc,['0','1'],true)){$set[]='comments_enabled=?';$vals[]=(int)$bc;}
   if($bp!==''&&in_array((string)$bp,['0','1'],true)){$set[]='pings_enabled=?';$vals[]=(int)$bp;}
   if($set){$in=implode(',',array_fill(0,count($ids),'?'));$vals=array_merge($vals,[$type],$ids);db()->prepare('UPDATE cms_posts SET '.implode(',',$set).',updated_at=NOW() WHERE post_type=? AND id IN ('.$in.')')->execute($vals);}
   foreach($ids as $pid){if($bcat!=='') cms_save_terms($pid,array_filter(array_map('intval',explode(',',$bcat))),$btag!==''?array_column(cms_terms($pid,'tag'),'id'):array_column(cms_terms($pid,'tag'),'id')); if($btag!=='') cms_save_terms($pid,$bcat!==''?array_column(cms_terms($pid,'category'),'id'):array_column(cms_terms($pid,'category'),'id'),array_filter(array_map('intval',explode(',',$btag))));}
   flash('success','Bulk edit applied to '.count($ids).' item(s).'); redirect('/admin/'.$type.'s/');
 }
 if($ids&&in_array($action,['publish','trash','restore','delete'],true)){
   $in=implode(',',array_fill(0,count($ids),'?'));
   if($action==='publish') db()->prepare("UPDATE cms_posts SET status='published',published_at=COALESCE(published_at,NOW()),deleted_at=NULL,updated_at=NOW() WHERE post_type=? AND id IN ($in)")->execute(array_merge([$type],$ids));
   elseif($action==='trash') db()->prepare("UPDATE cms_posts SET status='trash',deleted_at=NOW(),updated_at=NOW() WHERE post_type=? AND id IN ($in)")->execute(array_merge([$type],$ids));
   elseif($action==='restore') db()->prepare("UPDATE cms_posts SET status='draft',deleted_at=NULL,updated_at=NOW() WHERE post_type=? AND id IN ($in)")->execute(array_merge([$type],$ids));
   else db()->prepare("DELETE FROM cms_posts WHERE post_type=? AND id IN ($in)")->execute(array_merge([$type],$ids));
   flash('success','CMS bulk action completed.'); redirect('/admin/'.$type.'s/');
 }
}
$status=(string)getv('status','all'); $q=trim((string)getv('q','')); $cat=(int)getv('cat',0); $author=(int)getv('author',0); $date=(string)getv('date','');
$where=['p.post_type=?']; $args=[$type];
if(in_array($status,['published','draft','trash','pending'],true)){$where[]='p.status=?';$args[]=$status;}else{$where[]="p.status<>'trash'";}
if($q!==''){$where[]='(p.title LIKE ? OR p.slug LIKE ? OR p.content LIKE ?)';$args[]="%$q%";$args[]="%$q%";$args[]="%$q%";}
if($cat>0){$where[]='EXISTS (SELECT 1 FROM cms_post_categories x WHERE x.post_id=p.id AND x.category_id=?)';$args[]=$cat;}
if($author>0){$where[]='p.author_id=?';$args[]=$author;}
if(preg_match('/^\d{4}-\d{2}$/',$date)){$where[]='DATE_FORMAT(p.updated_at,"%Y-%m")=?';$args[]=$date;}
$sql="SELECT p.*,u.full_name author_name,u.email author_email,(SELECT COUNT(*) FROM cms_comments c WHERE c.post_id=p.id AND c.status='approved') comment_count,(SELECT COUNT(*) FROM cms_comments c WHERE c.post_id=p.id AND c.status='pending') pending_comment_count,(SELECT GROUP_CONCAT(DISTINCT c.name ORDER BY c.name SEPARATOR ', ') FROM cms_post_categories pc INNER JOIN cms_categories c ON c.id=pc.category_id WHERE pc.post_id=p.id) category_names,(SELECT GROUP_CONCAT(DISTINCT t.name ORDER BY t.name SEPARATOR ', ') FROM cms_post_tags pt INNER JOIN cms_tags t ON t.id=pt.tag_id WHERE pt.post_id=p.id) tag_names FROM cms_posts p LEFT JOIN users u ON u.id=p.author_id WHERE ".implode(' AND ',$where).' ORDER BY p.updated_at DESC';
$s=db()->prepare($sql);$s->execute($args);$rows=$s->fetchAll();$counts=cms_status_counts($type);
$cats=db()->query('SELECT id,name FROM cms_categories ORDER BY name')->fetchAll();$users=db()->query("SELECT id,full_name,email FROM users WHERE status='active' ORDER BY full_name")->fetchAll();$tags=db()->query('SELECT id,name FROM cms_tags ORDER BY name')->fetchAll();
$months=db()->query("SELECT DISTINCT DATE_FORMAT(updated_at,'%Y-%m') ym FROM cms_posts WHERE post_type='".$type."' ORDER BY ym DESC LIMIT 24")->fetchAll(PDO::FETCH_COLUMN);
$title=$label.' · CMS';require __DIR__.'/../includes/header.php';
?>
<div class="page-head cms-head"><div><span class="eyebrow">Content Management</span><h1><?=$label?></h1><p>Manage content with filters, bulk editing, Quick Edit, revisions and publishing controls.</p></div><div class="actions"><a class="btn" href="/admin/<?=$type?>s/edit/">+ Add <?=$type?></a><a class="btn secondary" href="/admin/<?= $type==='post'?'pages':'posts' ?>/">Switch to <?= $type==='post'?'Pages':'Posts' ?></a></div></div>
<div class="card cms-toolbar"><div class="cms-filters"><?php foreach(['all'=>'All','published'=>'Published','draft'=>'Drafts','trash'=>'Trash','pending'=>'Pending'] as $k=>$v):?><a class="pill <?=($status===$k?'active':'')?>" href="?status=<?=$k?><?= $q!==''?'&q='.urlencode($q):''?>&cat=<?=$cat?>&author=<?=$author?>&date=<?=urlencode($date)?>"><?=$v?> <strong><?=number_format($counts[$k])?></strong></a><?php endforeach;?></div><form class="cms-search" method="get"><input name="q" value="<?=e($q)?>" placeholder="Search <?=$type?>s…"><input type="hidden" name="status" value="<?=e($status)?>"><input type="hidden" name="cat" value="<?=$cat?>"><input type="hidden" name="author" value="<?=$author?>"><input type="hidden" name="date" value="<?=e($date)?>"><button class="btn" type="submit">Search</button></form></div>
<form class="card cms-filter-panel" method="get"><input type="hidden" name="status" value="<?=e($status)?>"> <label>Category<select name="cat"><option value="0">All categories</option><?php foreach($cats as $c):?><option value="<?=$c['id']?>" <?=($cat===$c['id']?'selected':'')?>><?=e($c['name'])?></option><?php endforeach;?></select></label><label>Author<select name="author"><option value="0">All authors</option><?php foreach($users as $u):?><option value="<?=$u['id']?>" <?=($author===$u['id']?'selected':'')?>><?=e($u['full_name']?:$u['email'])?></option><?php endforeach;?></select></label><label>Month<select name="date"><option value="">Any month</option><?php foreach($months as $m):?><option value="<?=e($m)?>" <?=($date===$m?'selected':'')?>><?=e(date('F Y',strtotime($m.'-01'))) ?></option><?php endforeach;?></select></label><input type="hidden" name="q" value="<?=e($q)?>"><button class="btn secondary" type="submit">Filter</button><a class="btn small secondary" href="/admin/<?=$type?>s/">Reset</a></form>
<form method="post" id="cmsBulk" class="cms-bulk-form"><?=csrf_field()?><input type="hidden" name="action" id="cmsAction"><input type="hidden" name="bulk_author" id="bulkAuthor"><input type="hidden" name="bulk_status" id="bulkStatus"><input type="hidden" name="bulk_comments" id="bulkComments"><input type="hidden" name="bulk_pings" id="bulkPings"><input type="hidden" name="bulk_categories" id="bulkCategories"><input type="hidden" name="bulk_tags" id="bulkTags"><div class="card table-wrap cms-table-card"><div class="bulkbar"><label class="check"><input type="checkbox" data-check-all="#cmsBulk input[name='ids[]']"> Select all</label><button class="btn small secondary" type="button" data-cms-action="publish">Publish</button><button class="btn small secondary" type="button" data-open-bulk-edit>Bulk Edit</button><button class="btn small secondary" type="button" data-cms-action="trash">Move to Trash</button><?php if($status==='trash'):?><button class="btn small secondary" type="button" data-cms-action="restore">Restore</button><button class="btn small danger" type="button" data-cms-action="delete">Delete Permanently</button><?php endif;?></div><table class="cms-table"><thead><tr><th></th><th>Title</th><th class="col-author">Author</th><th class="col-taxonomy">Categories</th><th class="col-taxonomy">Tags</th><th class="col-comments">Comments</th><th class="col-date">Date</th></tr></thead><tbody>
<?php if(!$rows):?><tr><td colspan="7"><div class="empty-state"><h3>No <?=$type?>s found</h3><p>Create your first item or change the filters.</p></div></td></tr><?php endif; foreach($rows as $r): $statusText=ucfirst($r['status']);?><tr><td><input type="checkbox" name="ids[]" value="<?=$r['id']?>"></td><td><strong><a href="/admin/<?=$type?>s/edit/?id=<?=$r['id']?>"><?=e($r['title']?:'(no title)')?></a></strong><div class="row-status"><span class="status-badge status-<?=e($r['status'])?>"><?=$statusText?></span><?php if((int)$r['pending_comment_count']>0):?><span class="status-badge status-pending"><?=number_format($r['pending_comment_count'])?> pending</span><?php endif;?></div><div class="row-actions"><a href="/admin/<?=$type?>s/edit/?id=<?=$r['id']?>">Edit</a><button type="button" data-quick-edit data-id="<?=$r['id']?>" data-title="<?=e($r['title'])?>" data-slug="<?=e($r['slug'])?>" data-status="<?=e($r['status'])?>" data-author="<?=$r['author_id']?>" data-comments="<?=$r['comments_enabled']?>" data-pings="<?=$r['pings_enabled']?>" data-date="<?=e(date('Y-m-d\TH:i',strtotime($r['updated_at'])))?>" data-cats="<?=e(implode(',',array_column(cms_terms((int)$r['id'],'category'),'id')))?>" data-tags="<?=e(implode(',',array_column(cms_terms((int)$r['id'],'tag'),'id')))?>">Quick Edit</button><?php if($r['status']!=='trash'):?><button type="button" data-single-action="trash" data-id="<?=$r['id']?>">Trash</button><?php else:?><button type="button" data-single-action="delete" data-id="<?=$r['id']?>">Delete</button><?php endif;?><a href="/posts/?slug=<?=urlencode($r['slug'])?>" target="_blank">View</a></div></td><td class="col-author"><a href="?author=<?=$r['author_id']?>&status=<?=e($status)?>"><?=e($r['author_name']?:'—')?></a></td><td class="col-taxonomy"><?=e($r['category_names']?:'—')?></td><td class="col-taxonomy"><?=e($r['tag_names']?:'—')?></td><td class="col-comments"><a href="/admin/comments/?post=<?=$r['id']?>"><?=number_format((int)$r['comment_count'])?></a></td><td class="col-date"><strong><?=e($statusText)?></strong><br><small><?=e(date('M j, Y',strtotime($r['updated_at'])))?></small></td></tr><?php endforeach;?></tbody></table></div></form>
<div class="cms-modal" id="quickEditModal" hidden><div class="cms-modal-backdrop" data-close-cms-modal></div><div class="cms-modal-dialog"><div class="page-head"><div><span class="eyebrow">Quick Edit</span><h2>Update <?=$type?></h2></div><button type="button" class="modal-close" data-close-cms-modal>×</button></div><form method="post" action="/admin/<?=$type?>s/edit/"><?=csrf_field()?><input type="hidden" name="quick_edit" value="1"><input type="hidden" name="id" id="quickId"><input type="hidden" name="type" value="<?=$type?>"><label>Title<input name="title" id="quickTitle" required></label><label>Slug<input name="slug" id="quickSlug"></label><div class="grid2"><label>Date / time<input type="datetime-local" name="edit_date" id="quickDate"></label><label>Password (leave blank to keep)<input type="password" name="password" id="quickPassword" autocomplete="new-password"></label></div><div class="grid2"><label>Status<select name="status" id="quickStatus"><option value="draft">Draft</option><option value="pending">Pending</option><option value="published">Published</option><option value="private">Private</option></select></label><label>Author<select name="author_id" id="quickAuthor"><?php foreach($users as $u):?><option value="<?=$u['id']?>"><?=e($u['full_name']?:$u['email'])?></option><?php endforeach;?></select></label></div><label class="check"><input type="checkbox" name="comments_enabled" id="quickComments"> Allow comments</label><label class="check"><input type="checkbox" name="pings_enabled" id="quickPings"> Allow trackbacks / pingbacks</label><div class="grid2"><label>Categories<select multiple name="categories[]" id="quickCategories" size="5"><?php foreach($cats as $c):?><option value="<?=$c['id']?>"><?=e($c['name'])?></option><?php endforeach;?></select></label><label>Tags<select multiple name="tags[]" id="quickTags" size="5"><?php foreach($tags as $t):?><option value="<?=$t['id']?>"><?=e($t['name'])?></option><?php endforeach;?></select></label></div><div class="actions"><button class="btn" type="submit">Update</button><button class="btn secondary" type="button" data-close-cms-modal>Cancel</button></div></form></div></div>
